WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_language_cloze_comprehensive_multi_blank'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多空综合', 'kp-xingce-language-cloze-comprehensive-multi-blank', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多空综合秒杀"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "寻找最确定的那个“突破口”。千万不要按顺序从第一空做到最后一空！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到三个空的题] --> B[迅速扫视这三空的前后语境]\nB --> C[找到带有最明显提示线索(如固定搭配、极端色彩)的那个空]\nC --> D[利用这个空的绝对排他性, 直接排除掉 2-3 个选项]\nD --> E[再用剩下的 1-2 个选项去验证其他空是否通顺]"}}]}$$ AS jsonb), NULL, '多空综合的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "多空综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_comprehensive_multi_blank", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
